import { readFile } from "node:fs/promises";
import { z } from "zod";

const RunScope = z.object({
  repo: z.string().regex(/^RhinoHealth\/[\w.-]+$/),
  branch: z.string().startsWith("nova/"),
});

const [command, file] = process.argv.slice(2);
if (command !== "check" || !file) {
  console.error("usage: lab-worker check <scope.json>");
  process.exit(2);
}
const result = RunScope.safeParse(JSON.parse(await readFile(file, "utf8")));
console.log(result.success ? `ok: ${result.data.repo} ${result.data.branch}` : z.prettifyError(result.error));
process.exitCode = result.success ? 0 : 1;

